const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "OSSInsight";
pres.title = "GitHub Trending Repos Snapshot: The Rise of AI Coding Agents & Claude Code Skills";

// Color palette - Midnight Executive with tech edge
const COLORS = {
  darkBg: "0F172A",      // Slate 900 - dark backgrounds
  primary: "1E3A5F",    // Deep navy
  accent: "3B82F6",      // Blue 500 - accent
  accentLight: "60A5FA", // Blue 400 - lighter accent
  teal: "0D9488",       // Teal 700
  mint: "10B981",       // Emerald 500
  lightBg: "F8FAFC",    // Slate 50 - content slides
  cardBg: "FFFFFF",     // White cards
  textDark: "1E293B",   // Slate 800
  textMuted: "64748B",  // Slate 500
  textLight: "F1F5F9",  // Slate 100
  gridLine: "E2E8F0",   // Slate 200
  python: "3B82F6",      // Blue for Python
  ts: "14B8A6",         // Teal for TypeScript
  html: "F59E0B",       // Amber for HTML
  rust: "DC2626",       // Red for Rust
  swift: "EF4444",      // Red for Swift
  shell: "22C55E",      // Green for Shell
  java: "F97316",       // Orange for Java
  unspecified: "94A3B8" // Slate for Unspecified
};

// Helper for shadows - fresh object each time
const makeShadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

// ============ SLIDE 1: Title Slide ============
const slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkBg };

// Decorative gradient bar at top
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.15,
  fill: { color: COLORS.accent }
});

// Main title
slide1.addText("GitHub Trending Repos Snapshot", {
  x: 0.5, y: 1.5, w: 9, h: 0.9,
  fontSize: 40, fontFace: "Arial", bold: true,
  color: COLORS.textLight, align: "left", margin: 0
});

// Subtitle
slide1.addText("The Rise of AI Coding Agents & Claude Code Skills", {
  x: 0.5, y: 2.4, w: 9, h: 0.6,
  fontSize: 24, fontFace: "Arial",
  color: COLORS.accentLight, align: "left", margin: 0
});

// Accent line
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.2, w: 2, h: 0.04,
  fill: { color: COLORS.accent }
});

// Data source callout
slide1.addText("Powered by OSSInsight — 10.6B+ GitHub events analyzed", {
  x: 0.5, y: 3.6, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// Date context
slide1.addText("Past 24 Hours | April 27, 2026", {
  x: 0.5, y: 4.8, w: 9, h: 0.4,
  fontSize: 12, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// ============ SLIDE 2: Platform Overview ============
const slide2 = pres.addSlide();
slide2.background = { color: COLORS.lightBg };

// Title
slide2.addText("OSSInsight Tracks 10.6 Billion GitHub Events in Real Time", {
  x: 0.5, y: 0.4, w: 9, h: 0.7,
  fontSize: 28, fontFace: "Arial", bold: true,
  color: COLORS.textDark, align: "left", margin: 0
});

// Subtitle
slide2.addText("Real-time analytics platform ranking trending repositories across all programming languages", {
  x: 0.5, y: 1.0, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// Stat cards - 4 metrics
const metrics = [
  { value: "10.6B+", label: "GitHub Events", color: COLORS.accent },
  { value: "4", label: "Score Components", color: COLORS.teal },
  { value: "20", label: "Trending Repos", color: COLORS.mint },
  { value: "24h", label: "Time Window", color: COLORS.primary }
];

metrics.forEach((metric, i) => {
  const x = 0.5 + i * 2.35;

  // Card background
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.8, w: 2.15, h: 1.6,
    fill: { color: COLORS.cardBg },
    shadow: makeShadow()
  });

  // Colored top accent
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: x, y: 1.8, w: 2.15, h: 0.08,
    fill: { color: metric.color }
  });

  // Value
  slide2.addText(metric.value, {
    x: x, y: 2.0, w: 2.15, h: 0.8,
    fontSize: 32, fontFace: "Arial", bold: true,
    color: COLORS.textDark, align: "center", valign: "middle", margin: 0
  });

  // Label
  slide2.addText(metric.label, {
    x: x, y: 2.8, w: 2.15, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: COLORS.textMuted, align: "center", valign: "top", margin: 0
  });
});

// Score formula explanation
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.8, w: 9, h: 1.4,
  fill: { color: COLORS.cardBg },
  shadow: makeShadow()
});

slide2.addText("Total Score Formula", {
  x: 0.7, y: 3.95, w: 8, h: 0.4,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.textDark, align: "left", margin: 0
});

slide2.addText("Stars Score + Forks Score + Base Score", {
  x: 0.7, y: 4.35, w: 8, h: 0.35,
  fontSize: 18, fontFace: "Arial",
  color: COLORS.accent, align: "left", margin: 0
});

slide2.addText("Tracked metrics: stars, commits, pull requests, issues, contributors, and community health", {
  x: 0.7, y: 4.75, w: 8, h: 0.35,
  fontSize: 12, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// ============ SLIDE 3: Top 5 Trending Repos ============
const slide3 = pres.addSlide();
slide3.background = { color: COLORS.lightBg };

// Title
slide3.addText("hermes-agent Leads with 1,347 Stars", {
  x: 0.5, y: 0.4, w: 9, h: 0.6,
  fontSize: 28, fontFace: "Arial", bold: true,
  color: COLORS.textDark, align: "left", margin: 0
});

slide3.addText("Top 5 Repos by Total Score", {
  x: 0.5, y: 0.95, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// Top 5 repos data
const top5Repos = [
  { rank: "#1", repo: "NousResearch/hermes-agent", stars: 1347, forks: 101, pushes: 42, prs: 78, lang: "Python" },
  { rank: "#2", repo: "safishamsan/graphify", stars: 742, forks: 50, pushes: 6, prs: 5, lang: "Python" },
  { rank: "#3", repo: "VoltAgent/awesome-design-md", stars: 615, forks: 48, pushes: 1, prs: 0, lang: "HTML" },
  { rank: "#4", repo: "JuliusBrussee/caveman", stars: 300, forks: 11, pushes: 1, prs: 1, lang: "Python" },
  { rank: "#5", repo: "shanraisshan/claude-code-best-practice", stars: 304, forks: 23, pushes: 0, prs: 0, lang: "HTML" }
];

// Table header
const tableHeader = [
  { text: "Rank", options: { fill: { color: COLORS.primary }, color: "FFFFFF", bold: true, align: "center" } },
  { text: "Repository", options: { fill: { color: COLORS.primary }, color: "FFFFFF", bold: true, align: "left" } },
  { text: "Stars", options: { fill: { color: COLORS.primary }, color: "FFFFFF", bold: true, align: "center" } },
  { text: "Forks", options: { fill: { color: COLORS.primary }, color: "FFFFFF", bold: true, align: "center" } },
  { text: "Pushes", options: { fill: { color: COLORS.primary }, color: "FFFFFF", bold: true, align: "center" } },
  { text: "PRs", options: { fill: { color: COLORS.primary }, color: "FFFFFF", bold: true, align: "center" } }
];

const tableRows = top5Repos.map((repo, i) => {
  const isFirst = i === 0;
  const bgColor = isFirst ? "DBEAFE" : "F8FAFC"; // Light blue for #1
  return [
    { text: repo.rank, options: { fill: { color: bgColor }, color: COLORS.textDark, bold: isFirst, align: "center" } },
    { text: repo.repo, options: { fill: { color: bgColor }, color: COLORS.textDark, bold: isFirst, align: "left" } },
    { text: repo.stars.toLocaleString(), options: { fill: { color: bgColor }, color: COLORS.accent, bold: isFirst, align: "center" } },
    { text: repo.forks.toLocaleString(), options: { fill: { color: bgColor }, color: COLORS.textDark, align: "center" } },
    { text: repo.pushes.toLocaleString(), options: { fill: { color: bgColor }, color: COLORS.textDark, align: "center" } },
    { text: repo.prs.toLocaleString(), options: { fill: { color: bgColor }, color: COLORS.textDark, align: "center" } }
  ];
});

slide3.addTable([tableHeader, ...tableRows], {
  x: 0.5, y: 1.5, w: 9, h: 2.8,
  colW: [0.6, 3.4, 1.1, 1.1, 1.1, 1.1],
  border: { pt: 0.5, color: COLORS.gridLine },
  fontFace: "Arial",
  fontSize: 12
});

// Bar chart visualization
slide3.addChart(pres.charts.BAR, [{
  name: "Stars",
  labels: top5Repos.map(r => r.rank),
  values: top5Repos.map(r => r.stars)
}], {
  x: 0.5, y: 3.6, w: 9, h: 1.8,
  barDir: "bar",
  chartColors: [COLORS.accent],
  showValue: false,
  showLegend: false,
  catAxisLabelColor: COLORS.textDark,
  valAxisLabelColor: COLORS.textMuted,
  valGridLine: { color: COLORS.gridLine, size: 0.5 },
  catGridLine: { style: "none" },
  chartArea: { fill: { color: COLORS.lightBg } }
});

// ============ SLIDE 4: Language Distribution ============
const slide4 = pres.addSlide();
slide4.background = { color: COLORS.lightBg };

// Title
slide4.addText("Python and TypeScript Dominate Trending Repos' Language Mix", {
  x: 0.5, y: 0.4, w: 9, h: 0.6,
  fontSize: 28, fontFace: "Arial", bold: true,
  color: COLORS.textDark, align: "left", margin: 0
});

slide4.addText("Distribution across top 20 trending repositories", {
  x: 0.5, y: 0.95, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// Donut chart
slide4.addChart(pres.charts.DOUGHNUT, [{
  name: "Languages",
  labels: ["Python (7)", "TypeScript (4)", "HTML (2)", "Rust (2)", "Swift (2)", "Shell (1)", "Java (1)", "Unspecified (1)"],
  values: [7, 4, 2, 2, 2, 1, 1, 1]
}], {
  x: 0.5, y: 1.4, w: 5, h: 3.8,
  chartColors: [COLORS.python, COLORS.ts, COLORS.html, COLORS.rust, COLORS.swift, COLORS.shell, COLORS.java, COLORS.unspecified],
  showPercent: true,
  showLegend: true,
  legendPos: "r",
  holeSize: 50,
  chartArea: { fill: { color: COLORS.lightBg } }
});

// Insight cards on right
const langInsights = [
  { lang: "Python", count: "7 repos", pct: "35%", note: "AI/ML ecosystem core" },
  { lang: "TypeScript", count: "4 repos", pct: "20%", note: "Agent UIs & dev tools" },
  { lang: "Other", count: "9 repos", pct: "45%", note: "HTML, Rust, Swift, Shell, Java" }
];

langInsights.forEach((insight, i) => {
  const y = 1.5 + i * 1.25;

  slide4.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: y, w: 3.7, h: 1.1,
    fill: { color: COLORS.cardBg },
    shadow: makeShadow()
  });

  slide4.addText(insight.lang, {
    x: 6.0, y: y + 0.15, w: 1.5, h: 0.35,
    fontSize: 14, fontFace: "Arial", bold: true,
    color: COLORS.textDark, align: "left", margin: 0
  });

  slide4.addText(insight.count, {
    x: 7.5, y: y + 0.15, w: 1.5, h: 0.35,
    fontSize: 14, fontFace: "Arial", bold: true,
    color: COLORS.accent, align: "right", margin: 0
  });

  slide4.addText(insight.pct, {
    x: 6.0, y: y + 0.5, w: 1.0, h: 0.3,
    fontSize: 20, fontFace: "Arial", bold: true,
    color: COLORS.accent, align: "left", margin: 0
  });

  slide4.addText(insight.note, {
    x: 7.0, y: y + 0.5, w: 2.3, h: 0.3,
    fontSize: 11, fontFace: "Arial",
    color: COLORS.textMuted, align: "left", margin: 0
  });
});

// ============ SLIDE 5: Category Breakdown ============
const slide5 = pres.addSlide();
slide5.background = { color: COLORS.lightBg };

// Title
slide5.addText("14 of 20 Trending Repos Are AI Coding Agent or Claude Code Projects", {
  x: 0.5, y: 0.4, w: 9, h: 0.6,
  fontSize: 26, fontFace: "Arial", bold: true,
  color: COLORS.textDark, align: "left", margin: 0
});

slide5.addText("Thematic categorization of top 20 trending repositories", {
  x: 0.5, y: 0.95, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// Stacked bar showing categories
const categories = [
  { name: "AI Coding Agents & Skills", count: 10, color: COLORS.accent },
  { name: "Claude Code Ecosystem", count: 5, color: COLORS.teal },
  { name: "AI Infrastructure", count: 3, color: COLORS.html },
  { name: "Developer Utilities", count: 3, color: COLORS.mint }
];

// Draw stacked horizontal bar
let barX = 0.5;
const barY = 2.0;
const totalWidth = 9;
const barHeight = 0.8;
const total = 21; // total repos

categories.forEach((cat, i) => {
  const width = (cat.count / total) * totalWidth;
  const isFirst = i === 0;

  slide5.addShape(pres.shapes.RECTANGLE, {
    x: barX, y: barY, w: width, h: barHeight,
