const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "OSSInsight";
pres.title = "GitHub Trending Repos Snapshot: The Rise of AI Coding Agents & Claude Code Skills";

// Color palette - Midnight Executive with tech edge
const COLORS = {
  darkBg: "0F172A",      // Slate 900 - dark backgrounds
  primary: "1E3A5F",    // Deep navy
  accent: "3B82F6",      // Blue 500 - accent
  accentLight: "60A5FA", // Blue 400 - lighter accent
  teal: "0D9488",       // Teal 700
  mint: "10B981",       // Emerald 500
  lightBg: "F8FAFC",    // Slate 50 - content slides
  cardBg: "FFFFFF",     // White cards
  textDark: "1E293B",   // Slate 800
  textMuted: "64748B",  // Slate 500
  textLight: "F1F5F9",  // Slate 100
  gridLine: "E2E8F0",   // Slate 200
  python: "3B82F6",      // Blue for Python
  ts: "14B8A6",         // Teal for TypeScript
  html: "F59E0B",       // Amber for HTML
  rust: "DC2626",       // Red for Rust
  swift: "EF4444",      // Red for Swift
  shell: "22C55E",      // Green for Shell
  java: "F97316",       // Orange for Java
  unspecified: "94A3B8" // Slate for Unspecified
};

// Helper for shadows - fresh object each time
const makeShadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

// ============ SLIDE 1: Title Slide ============
const slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkBg };

// Decorative gradient bar at top
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.15,
  fill: { color: COLORS.accent }
});

// Main title
slide1.addText("GitHub Trending Repos Snapshot", {
  x: 0.5, y: 1.5, w: 9, h: 0.9,
  fontSize: 40, fontFace: "Arial", bold: true,
  color: COLORS.textLight, align: "left", margin: 0
});

// Subtitle
slide1.addText("The Rise of AI Coding Agents & Claude Code Skills", {
  x: 0.5, y: 2.4, w: 9, h: 0.6,
  fontSize: 24, fontFace: "Arial",
  color: COLORS.accentLight, align: "left", margin: 0
});

// Accent line
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.2, w: 2, h: 0.04,
  fill: { color: COLORS.accent }
});

// Data source callout
slide1.addText("Powered by OSSInsight — 10.6B+ GitHub events analyzed", {
  x: 0.5, y: 3.6, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// Date context
slide1.addText("Past 24 Hours | April 27, 2026", {
  x: 0.5, y: 4.8, w: 9, h: 0.4,
  fontSize: 12, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// ============ SLIDE 2: Platform Overview ============
const slide2 = pres.addSlide();
slide2.background = { color: COLORS.lightBg };

// Title
slide2.addText("OSSInsight Tracks 10.6 Billion GitHub Events in Real Time", {
  x: 0.5, y: 0.55, w: 9, h: 0.7,
  fontSize: 28, fontFace: "Arial", bold: true,
