slide6.background = { color: COLORS.lightBg };

// Title - fixed margin to 0.55
slide6.addText("Claude Code Spawns an Ecosystem", {
  x: 0.5, y: 0.55, w: 9, h: 0.6,
  fontSize: 28, fontFace: "Arial", bold: true,
  color: COLORS.textDark, align: "left", margin: 0
});

slide6.addText("Skills, Guides, Switches, and Best Practices", {
  x: 0.5, y: 1.1, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// Core Claude Code repos - left column
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.6, w: 4.3, h: 3.3,
  fill: { color: COLORS.cardBg },
  shadow: makeShadow()
});

slide6.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.6, w: 4.3, h: 0.5,
  fill: { color: COLORS.teal }
});

slide6.addText("Core Claude Code Tools (5 repos)", {
  x: 0.6, y: 1.65, w: 4.1, h: 0.4,
  fontSize: 13, fontFace: "Arial", bold: true,
  color: "FFFFFF", align: "left", valign: "middle", margin: 0
});

const coreRepos = [
  "claude-code-best-practice — Practice made Claude perfect",
  "claude-howto — Visual guide to Claude Code",
  "cc-switch — Cross-platform all-in-one assistant",
  "caveman — Cuts 75% of tokens by talking like caveman",
  "learn-claude-code — Nano Claude Code-like agent"
];

coreRepos.forEach((repo, i) => {
  slide6.addText(repo, {
    x: 0.7, y: 2.2 + i * 0.5, w: 3.9, h: 0.45,
    fontSize: 11, fontFace: "Arial",
    color: COLORS.textDark, align: "left", valign: "top", margin: 0
  });
});

// Extended ecosystem - right column
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 5.2, y: 1.6, w: 4.3, h: 3.3,
  fill: { color: COLORS.cardBg },
  shadow: makeShadow()
});

slide6.addShape(pres.shapes.RECTANGLE, {
  x: 5.2, y: 1.6, w: 4.3, h: 0.5,
  fill: { color: COLORS.accent }
});

slide6.addText("Extended Ecosystem (7+ repos)", {
  x: 5.3, y: 1.65, w: 4.1, h: 0.4,
  fontSize: 13, fontFace: "Arial", bold: true,
  color: "FFFFFF", align: "left", valign: "middle", margin: 0
});

const extendedRepos = [
  "oh-my-codex — Add hooks, agent teams, HUDs",
  "agent-skills — Production-grade engineering skills",
  "graphify — Queryable knowledge graph for coding agents",
  "multica — Coding agents as real teammates",
  "DeepTutor — Agent-native personalized learning"
];

extendedRepos.forEach((repo, i) => {
  slide6.addText(repo, {
    x: 5.4, y: 2.2 + i * 0.5, w: 3.9, h: 0.45,
    fontSize: 11, fontFace: "Arial",
    color: COLORS.textDark, align: "left", valign: "top", margin: 0
  });
});

// Key insight - fixed margin
slide6.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 5.0, w: 9, h: 0.4,
  fill: { color: "DBEAFE" }
});

slide6.addText("At least 7 repos are Claude Code skills, guides, best-practice collections, or multi-tool switchers", {
  x: 0.6, y: 5.05, w: 8.8, h: 0.3,
  fontSize: 11, fontFace: "Arial",
  color: COLORS.accent, align: "center", valign: "middle", margin: 0
});

// ============ SLIDE 7: Community Engagement ============
const slide7 = pres.addSlide();
slide7.background = { color: COLORS.lightBg };

// Title - fixed margin to 0.55
slide7.addText("hermes-agent Draws 78 PRs and 42 Pushes", {
  x: 0.5, y: 0.55, w: 9, h: 0.6,
  fontSize: 28, fontFace: "Arial", bold: true,
  color: COLORS.textDark, align: "left", margin: 0
});

slide7.addText("Community Engagement Metrics Across Top 20 Repos", {
  x: 0.5, y: 1.1, w: 9, h: 0.4,
  fontSize: 14, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// Plot background
const plotX = 0.5;
const plotY = 1.6;
const plotW = 6.0;
const plotH = 3.0;
const maxPRs = 80;
const maxPushes = 45;

slide7.addShape(pres.shapes.RECTANGLE, {
  x: plotX, y: plotY, w: plotW, h: plotH,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.gridLine, width: 1 }
});

// Grid lines
for (let i = 0; i <= 4; i++) {
  const y = plotY + (plotH / 4) * i;
  slide7.addShape(pres.shapes.LINE, {
    x: plotX, y: y, w: plotW, h: 0,
    line: { color: COLORS.gridLine, width: 0.5 }
  });
}

// Plot points - high engagement
const highEngage = [
  { repo: "hermes-agent", prs: 78, pushes: 42 },
  { repo: "multica", prs: 7, pushes: 35 }
];

highEngage.forEach((d) => {
  const cx = plotX + (d.prs / maxPRs) * plotW;
  const cy = plotY + plotH - (d.pushes / maxPushes) * plotH;

  slide7.addShape(pres.shapes.OVAL, {
    x: cx - 0.15, y: cy - 0.15, w: 0.3, h: 0.3,
    fill: { color: COLORS.accent }
  });

  slide7.addText(d.repo, {
    x: cx + 0.2, y: cy - 0.15, w: 1.5, h: 0.3,
    fontSize: 9, fontFace: "Arial", bold: true,
    color: COLORS.accent, align: "left", valign: "middle", margin: 0
  });
});

// Low engagement repos
const lowEngage = [
  { repo: "graphify", prs: 5, pushes: 6 },
  { repo: "rtk", prs: 5, pushes: 3 },
  { repo: "oh-my-codex", prs: 2, pushes: 10 },
  { repo: "cc-switch", prs: 2, pushes: 2 }
];

lowEngage.forEach((d) => {
  const cx = plotX + (d.prs / maxPRs) * plotW;
  const cy = plotY + plotH - (d.pushes / maxPushes) * plotH;

  slide7.addShape(pres.shapes.OVAL, {
    x: cx - 0.1, y: cy - 0.1, w: 0.2, h: 0.2,
    fill: { color: COLORS.textMuted }
  });
});

// Zero activity zone indicator
slide7.addText("8 repos with zero PRs", {
  x: plotX + 0.2, y: plotY + plotH - 0.4, w: 1.5, h: 0.3,
  fontSize: 10, fontFace: "Arial", italic: true,
  color: COLORS.textMuted, align: "left", valign: "middle", margin: 0
});

// Axis labels
slide7.addText("Pull Requests", {
  x: plotX + plotW / 2 - 0.6, y: plotY + plotH + 0.1, w: 1.2, h: 0.3,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.textMuted, align: "center", margin: 0
});

slide7.addText("Pushes", {
  x: plotX - 0.5, y: plotY + plotH / 2 - 0.15, w: 0.5, h: 0.3,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.textMuted, align: "center", margin: 0, rotate: 270
});

// Key findings panel - fixed margin
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 6.8, y: 1.6, w: 2.7, h: 3.0,
  fill: { color: COLORS.cardBg },
  shadow: makeShadow()
});

slide7.addText("Key Findings", {
  x: 6.95, y: 1.75, w: 2.4, h: 0.35,
  fontSize: 12, fontFace: "Arial", bold: true,
  color: COLORS.textDark, align: "left", margin: 0
});

const findings = [
  "hermes-agent: 78 PRs, 42 pushes — top engagement",
  "multica: 35 pushes, 7 PRs — second most active",
  "8 repos have zero PRs — early-stage projects",
  "Most repos below #8 show minimal activity"
];

findings.forEach((f, i) => {
  slide7.addText(f, {
    x: 6.95, y: 2.2 + i * 0.6, w: 2.4, h: 0.55,
    fontSize: 10, fontFace: "Arial",
    color: COLORS.textMuted, align: "left", valign: "top", margin: 0
  });
});

// ============ SLIDE 8: Key Takeaways ============
const slide8 = pres.addSlide();
slide8.background = { color: COLORS.darkBg };

// Accent bar at top
slide8.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.1,
  fill: { color: COLORS.accent }
});

// Title - fixed margin to 0.55
slide8.addText("Key Takeaways", {
  x: 0.5, y: 0.55, w: 9, h: 0.7,
  fontSize: 32, fontFace: "Arial", bold: true,
  color: COLORS.textLight, align: "left", margin: 0
});

slide8.addText("AI Coding Agents Are GitHub's Hottest Category", {
  x: 0.5, y: 1.15, w: 9, h: 0.4,
  fontSize: 16, fontFace: "Arial",
  color: COLORS.accentLight, align: "left", margin: 0
});

// Takeaway cards - fixed spacing
const takeaways = [
  {
    icon: "01",
    title: "70% AI Agent Dominance",
    desc: "14 of 20 repos relate to AI coding agents, skills, or Claude Code tooling — unprecedented concentration"
  },
  {
    icon: "02",
    title: "Claude Code Ecosystem Explosion",
    desc: "At least 7 repos are Claude Code skills, guides, best-practice collections, or multi-tool switchers"
  },
  {
    icon: "03",
    title: "Python Leads, TypeScript Follows",
    desc: "Python at 35% reflects AI/ML core; TypeScript at 20% drives agent UIs and developer experience"
  },
  {
    icon: "04",
    title: "Community Engagement is Top-Heavy",
    desc: "hermes-agent attracted 78 PRs in 24 hours; most repos below #8 show minimal collaborative activity"
  },
  {
    icon: "05",
    title: "Token Efficiency is a Hot Sub-Theme",
    desc: "caveman and rtk focus on reducing LLM token consumption — cost-consciousness as AI coding tools scale"
  }
];

takeaways.forEach((item, i) => {
  const y = 1.7 + i * 0.7;

  // Number circle
  slide8.addShape(pres.shapes.OVAL, {
    x: 0.5, y: y + 0.05, w: 0.4, h: 0.4,
    fill: { color: COLORS.accent }
  });

  slide8.addText(item.icon, {
    x: 0.5, y: y + 0.05, w: 0.4, h: 0.4,
    fontSize: 11, fontFace: "Arial", bold: true,
    color: "FFFFFF", align: "center", valign: "middle", margin: 0
  });

  // Title
  slide8.addText(item.title, {
    x: 1.05, y: y, w: 3.5, h: 0.3,
    fontSize: 14, fontFace: "Arial", bold: true,
    color: COLORS.textLight, align: "left", valign: "middle", margin: 0
  });

  // Description
  slide8.addText(item.desc, {
    x: 1.05, y: y + 0.28, w: 8.3, h: 0.4,
    fontSize: 11, fontFace: "Arial",
    color: COLORS.textMuted, align: "left", valign: "top", margin: 0
  });
});

// Footer - fixed margin
slide8.addText("Data Source: OSSInsight.io | 10.6B+ GitHub Events | April 27, 2026", {
  x: 0.5, y: 4.9, w: 9, h: 0.25,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.textMuted, align: "left", margin: 0
});

// Save the presentation
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Presentation saved successfully!"))
  .catch(err => console.error("Error saving presentation:", err));

